   <div className="alert-panel-tools">{permission==='default'&&<button onClick={onEnable}><Bell size={16}/> تفعيل إشعارات الجهاز</button>}{permission==='denied'&&<small>إشعارات الجهاز مرفوضة من المتصفح؛ تقدر تفعّلها من إعدادات الموقع.</small>}{data.unread>0&&<button className="text-button" onClick={onReadAll}>تعليم الكل كمقروء</button>}</div>
