function Login(){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError('');try{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;}catch{setError('تعذر الدخول. تأكد من البريد وكلمة المرور واتصال الإنترنت.');}finally{setBusy(false);}}return <div className="login"><div className="login-card"><Brand/><span className="eyebrow">SAYED ELSENOSY TECH</span><h1>مرحبًا بعودتك</h1><p>كل المتقدمين، المحادثات، والتنبيهات في لوحة واحدة سريعة وواضحة.</p><form onSubmit={submit}><label>البريد الإلكتروني<input type="email" dir="ltr" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@company.com"/></label><label>كلمة المرور<input type="password" dir="ltr" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••"/></label><Notice>{error}</Notice><button disabled={busy} className="primary full">{busy?'جارٍ الدخول…':'تسجيل الدخول'}<ArrowLeft size={18}/></button></form><small>الدخول بنفس حساب الـCRM على الويب والموبايل.</small></div><div className="login-art"><img className="login-brand-art" src={BRAND_IMAGE} alt="Sayed Elsenosy Tech"/><div className="login-kicker">INNOVATIVE SOLUTIONS · REAL IMPACT</div><span>Build Smarter.<br/><b>Together.</b></span><p>واجهة موحدة لإدارة التوظيف ومتابعة كل محادثة لحظيًا.</p><div className="tech-grid"/><div className="glow-orb glow-one"/><div className="glow-orb glow-two"/></div></div>;}
