  await action(async()=>{
   const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',path='staff/'+p.id+'/avatar.'+ext;
   const {error}=await supabase.storage.from('masar-documents').upload(path,file,{upsert:true,contentType:file.type,cacheControl:'3600'});if(error)throw error;
   await send('/profile',{...form,avatar_path:path},'PUT');await refresh();
  },'تم تحديث الصورة الشخصية');
